declare global {
    namespace Now {
        /**
         * @description used to populate a field with the contents of a file at build time. Often a script.
         * @param {string} filePath File path is relative to the file that is importing the file.
         * @example
         * import { Record } from '@servicenow/sdk/core'
         *
         * Record({
         *     $id: Now.ID['unique_id'],
         *     table: 'x_my_table',
         *     data: {
         *         name: 'My Record',
         *         script: Now.include('../scripts/myScript.js'),
         *         active: true,
         *         ...
         *     },
         * })
         * @returns {string}
         */
        function include(filePath: `./${string}` | `../${string}` | `${string}`): string
    }
}
